/**
 * Stand-in for SvelteKit's `$env/static/private` under Vitest.
 *
 * The real module is generated by SvelteKit's build from the environment, so a
 * plain unit test cannot resolve it. Aliased in `vitest.config.ts`.
 *
 * Unlike the dynamic stub, these are import-time constants — the real module
 * inlines them, so a test cannot reassign them either. Values are fixtures, not
 * defaults: a test asserting on one asserts on what is written here. A test
 * needing different values should `vi.mock('$env/static/private', …)` locally.
 */
export const ANKI_BRIDGE_URL = 'http://bridge.test:8092';
export const ANKI_BRIDGE_TOKEN = 'shared-secret';
export const ANKI_SYNC_PUBLIC_URL = 'https://anki.example.org/';
